'use strict'
// Real Minecraft inventory test, with a SIMULATED trusted bridge and enrolled
// user generated by the test harness. This MUST NOT be described as an actual
// server-side identity attestation for real offline-mode players.
const mineflayer=require('mineflayer')
const {Vec3}=require('vec3')
const {randomUUID,randomBytes,generateKeyPairSync,sign}=require('node:crypto')
const fs=require('node:fs')
const path=require('node:path')
const {inventoryCount}=require('../src/gather')
const {openDepositJournal,chestCount}=require('../src/deposit')
const {createQaSessionActionGateway}=require('../src/session_identity')

const directory=process.env.GUIAIA_QA_DEPOSIT_DIR
if(!directory?.startsWith('/tmp/guiaia-chest-qa-'))
  throw Error('Session QA must use a disposable Minecraft world')
const options=username=>({host:'127.0.0.1',port:25595,version:'1.21.1',
  auth:'offline',hideErrors:true,username})
const owner=mineflayer.createBot(options('OwnerQA'))
const bot=mineflayer.createBot(options('GuiaIA_QA'))
const chest={x:4,y:64,z:3}
const entries=[{name:'oak_log',count:1},{name:'birch_log',count:1}]
const sleep=ms=>new Promise(resolve=>setTimeout(resolve,ms))
const spawn=b=>b.entity?.position?Promise.resolve():new Promise((resolve,reject)=>{
  b.once('spawn',resolve)
  b.once('end',()=>reject(Error('Disposable Minecraft player ended')))
  b.once('error',()=>reject(Error('Disposable Minecraft player error')))
})
const pair=()=>generateKeyPairSync('ed25519')
const pub=k=>k.publicKey.export({type:'spki',format:'pem'})
const signed=(payload,k)=>({payload,
  signature:sign(null,Buffer.from(JSON.stringify(payload)),k.privateKey).toString('base64url')})
async function main(){
  const timeout=setTimeout(()=>{
    console.error('QA session Minecraft timeout')
    process.exitCode=1;owner.end();bot.end()
  },75000)
  let journal
  try {
    await Promise.all([spawn(owner),spawn(bot)])
    let ready=false
    for(let i=0;i<80;i++){
      if(bot.players?.OwnerQA?.entity &&
         bot.blockAt(new Vec3(chest.x,chest.y,chest.z))?.name==='chest' &&
         entries.every(x=>inventoryCount(bot,x.name)===1)) {
        ready=true;break
      }
      await sleep(150)
    }
    if(!ready)throw Error('Real Minecraft QA chest/items not ready')
    const bridge=pair(),principal=pair(),operator=pair()
    const worldId='qa:isolated:session:25595'
    const connectionId=randomUUID(),challenge=randomBytes(24).toString('hex')
    let live={worldId,connectionId,username:'OwnerQA',connected:true}
    let revoked=false
    const authority={sandboxOnly:true,identityMode:'trusted_server_bridge_lab',
      worldId,botName:'GuiaIA_QA',serverBridgePublicKeyPem:pub(bridge),
      trustedPrincipals:{qa_enrolled_player:pub(principal)},
      operatorPublicKeyPem:pub(operator),
      ledgerDirectory:path.join(directory,'spent-sessions'),
      activeConnection:()=>live,isRevoked:()=>revoked}
    const issue=item=>{
      const now=Date.now()
      const b={aud:'guiaia:server-connection:v1',worldId,connectionId,
        username:'OwnerQA',challenge,issuedAt:now-1000,expiresAt:now+45000}
      const o={aud:'guiaia:principal-proof:v1',worldId,connectionId,
        principalId:'qa_enrolled_player',challenge,issuedAt:now-1000,
        expiresAt:now+45000}
      const g={aud:'guiaia:session-deposit:v1',worldId,botName:'GuiaIA_QA',
        ownerName:'OwnerQA',principalId:'qa_enrolled_player',
        connectionId,challenge,chest:{...chest},
        item:item.name,count:item.count,nonce:randomUUID(),
        issuedAt:now-1000,expiresAt:now+60000}
      return {session:{bridge:signed(b,bridge),owner:signed(o,principal)},
        grant:signed(g,operator)}
    }
    const gateway=createQaSessionActionGateway(bot,authority)
    let denied=0
    const first=issue(entries[0])
    try{gateway.createDeposit({owner:first.session.owner},first.grant)}
    catch{denied++}
    const previous=live
    live={...previous,connectionId:randomUUID(),username:'OwnerQA'}
    try{gateway.createDeposit(first.session,first.grant)}
    catch{denied++}
    live=previous
    const bad={...first.grant,payload:{...first.grant.payload,
      chest:{x:5,y:64,z:3}}}
    try{gateway.createDeposit(first.session,bad)}
    catch{denied++}
    revoked=true
    try{gateway.createDeposit(first.session,first.grant)}
    catch{denied++}
    revoked=false
    if(denied!==4)throw Error('Spoofed/revoked session was authorized')
    if(entries.some(x=>inventoryCount(bot,x.name)!==1))
      throw Error('Rejected session mutated actual Minecraft inventory')
    journal=openDepositJournal(directory,{sandboxOnly:true,ownerName:'OwnerQA',
      chest,items:entries})
    let nonces=0
    for(const item of entries){
      const token=issue(item)
      const action=gateway.createDeposit(token.session,token.grant)
      const result=await journal.runNext(action)
      if(!result.ok)throw Error('Authenticated QA deposit failed: '+result.reason)
      nonces++
      try{
        await gateway.createDeposit(token.session,token.grant).depositOne()
        throw Error('CRITICAL: session grant replay succeeded')
      }catch(error){
        if(error.code!=='EEXIST')throw error
      }
    }
    const final={oak_log:inventoryCount(bot,'oak_log'),
      birch_log:inventoryCount(bot,'birch_log')}
    const window=await bot.openContainer(bot.blockAt(new Vec3(chest.x,chest.y,chest.z)))
    let stored
    try{stored={oak_log:chestCount(window,'oak_log'),
      birch_log:chestCount(window,'birch_log')}}
    finally{window.close()}
    if(final.oak_log!==0||final.birch_log!==0||
       stored.oak_log!==1||stored.birch_log!==1||
       journal.view().phase!=='completed'||journal.view().receipts.length!==2||
       fs.readdirSync(authority.ledgerDirectory).length!==2){
      throw Error('Real QA session deposit inventory or receipts invalid')
    }
    journal.close();journal=null
    console.log('GUIAIA_OFFLINE_SESSION_GATE_QA_EVIDENCE='+JSON.stringify({
      result:'pass',real_minecraft_server:true,
      simulated_test_bridge:true,
      simulated_test_principal_proof:true,
      real_server_bridge_implemented:false,
      offline_user_authenticated_in_production:false,
      denied_without_bridge:true,
      denied_same_nickname_other_connection:true,
      denied_forged_operator_chest:true,
      denied_revoked_principal:true,
      deposits_with_three_signatures:nonces,
      nonce_replay_denied:true,
      player_after:final,chest_after_reopen:stored,
      deposit_receipts:2,production:false,sandbox_only:true
    }))
  }finally{
    clearTimeout(timeout)
    if(journal)journal.close()
    owner.quit();bot.quit()
  }
}
main().catch(error=>{
  console.error('SESSION GATE MINECRAFT QA FAILED: '+String(error?.message).slice(0,420))
  process.exitCode=1;owner.end();bot.end()
})
